// --- Quest Journal tab -------------------------------------------------------

/**
 * Human-readable label for a quest node + status pair.
 * @param {string} node
 * @param {string} status
 * @returns {string}
 */
function questNodeLabel(node, status) {
  if (status === 'complete') return 'Complete';
  switch (node) {
    case 'offer':   return 'Offered';
    case 'survey':  return 'In Progress';
    case 'report':  return 'Ready to Report';
    default:        return node.charAt(0).toUpperCase() + node.slice(1);
  }
}

function appendRewardIcon(parent, item, size = 22) {
  const icon = document.createElement('span');
  const identity = String(item?.tooltip?.identity || item?.itemId || '');
  const fallback = String(item?.tooltip?.glyph || item?.glyph || '');
  applyAtlasIcon(icon, ITEM_ICON_ATLAS, identity, fallback, size);
  Object.assign(icon.style, { flex: '0 0 auto', verticalAlign: 'middle' });
  parent.appendChild(icon);
}

